async function toggleFavorite(){
  const q = currentQuestions[currentQuestionIndex];
  if(!q) return;
  const id = `fav_${currentUserId}_${q.id}`;
  const existing = await dbGetByKey('favorites', id);
  if(existing){
    await dbDelete('favorites', id);
    favoritedIds.delete(q.id);
  } else {
    await dbAdd('favorites', {
      id, userId:currentUserId, questionId:q.id,
      subject:q.subject, system:q.system, chapter:q.chapter, title:q.title,
      question:q, addedDate:new Date().toISOString()
    });
    favoritedIds.add(q.id);
  }
  const btn = document.getElementById('favBtn');
  if(btn) btn.textContent = favoritedIds.has(q.id) ? '⭐ 取消收藏' : '☆ 收藏';
}

async function recordAnswer(q, isCorrect, score){
  const record = {
    id:`rec_${currentUserId}_${q.id}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`,
    userId:currentUserId, questionId:q.id,
    subject:q.subject, system:q.system, chapter:q.chapter, title:q.title,
    correct:isCorrect, score:score,
    learnDate:new Date().toISOString(),
    learnDateStr:new Date().toDateString()
  };
  await dbAdd('records', record);
  // 更新错题的正确次数
  const wqId = `wq_${currentUserId}_${q.id}`;
  const existingWq = await dbGetByKey('wrongQuestions', wqId);
  if(existingWq){
    if(isCorrect){
      existingWq.correctCount = (existingWq.correctCount||0)+1;
      await dbAdd('wrongQuestions', existingWq);
    } else {
      existingWq.correctCount = existingWq.correctCount||0;
      await dbAdd('wrongQuestions', existingWq);
    }
  }
}

async function addToWrongQuestions(q){
  const id = `wq_${currentUserId}_${q.id}`;
  const existing = await dbGetByKey('wrongQuestions', id);
  if(existing){
    existing.wrongCount = (existing.wrongCount||0)+1;
    existing.lastWrongDate = new Date().toISOString();
    await dbAdd('wrongQuestions', existing);
  } else {
    await dbAdd('wrongQuestions', {
      id, userId:currentUserId, questionId:q.id,
      subject:q.subject, system:q.system, chapter:q.chapter, title:q.title,
      wrongCount:1, correctCount:0, lastWrongDate:new Date().toISOString(),
      question:q
    });
  }
}

