async function renderWrong(){
  const el = document.getElementById('wrongContent');
  let wrongQs = (await dbGetAll('wrongQuestions')).filter(w=>w.userId===currentUserId);

  let filterHtml = '<div class="filter-bar">';
  filterHtml += `<button class="filter-pill ${wrongFilterSubject==='all'?'active':''}" onclick="setWrongFilter('all')">全部</button>`;
  Object.entries(SUBJECTS).forEach(([key,sub])=>{
    const has = wrongQs.some(w=>w.subject===key);
    if(has){
      filterHtml += `<button class="filter-pill ${wrongFilterSubject===key?'active':''}" onclick="setWrongFilter('${key}')">${sub.icon} ${sub.name}</button>`;
    }
  });
  filterHtml += '</div>';

  if(wrongFilterSubject!=='all'){
    wrongQs = wrongQs.filter(w=>w.subject===wrongFilterSubject);
  }

  let listHtml = '';
  if(wrongQs.length===0){
    listHtml = '<div class="empty-state"><div class="es-icon">🎉</div><p>错题本为空，继续保持！</p></div>';
  } else {
    wrongQs.sort((a,b)=>new Date(b.lastWrongDate)-new Date(a.lastWrongDate));
    listHtml = wrongQs.map(w=>{
      const sub = SUBJECTS[w.subject] || {icon:'📝',name:'未知'};
      const fav = favoritedIds.has(w.questionId);
      return `<div class="error-card">
        <div class="ec-icon">${sub.icon}</div>
        <div class="ec-body">
          <div class="ec-title">${escapeHtml(w.title)}</div>
          <div class="ec-meta">${sub.name} · 最近：${formatDate(w.lastWrongDate)}</div>
          <div style="display:flex;gap:.3rem;margin-top:.3rem">
            <span style="background:var(--red-bg);color:var(--red);padding:.1rem .4rem;border-radius:4px;font-size:.65rem;font-weight:600">❌ ${w.wrongCount}次</span>
            <span style="background:var(--green-bg);color:var(--green);padding:.1rem .4rem;border-radius:4px;font-size:.65rem;font-weight:600">✅ ${w.correctCount||0}次</span>
          </div>
        </div>
        <div class="ec-actions">
          <button onclick="redoWrong('${w.questionId}')">重做</button>
          <button onclick="openNoteModal('${w.questionId}')">解析</button>
        </div>
      </div>`;
    }).join('');
  }

  el.innerHTML = `<h3 style="font-size:1rem;margin-bottom:1rem">❌ 错题本（共 ${wrongQs.length} 题）</h3>` + filterHtml + listHtml;
}

function setWrongFilter(subject){
  wrongFilterSubject = subject;
  renderWrong();
}

async function redoWrong(questionId){
  const w = await dbGetByKey('wrongQuestions', `wq_${currentUserId}_${questionId}`);
  if(!w || !w.question){
    alert('未找到该错题');
    return;
  }
  currentQuestions = [w.question];
  currentQuestionIndex = 0;
  const favs = (await dbGetAll('favorites')).filter(f=>f.userId===currentUserId);
  favoritedIds = new Set(favs.map(f=>f.questionId));
  switchPanel('quiz');
  renderQuestion();
}

/* ==========================================================
 * 3.9 学习统计
 * ========================================================== */
async function renderStats(){
  const el = document.getElementById('statsContent');
  const records = (await dbGetAll('records')).filter(r=>r.userId===currentUserId);
  const wrongQs = (await dbGetAll('wrongQuestions')).filter(w=>w.userId===currentUserId);

  // 7天柱状图
  const today = new Date(); today.setHours(0,0,0,0);
  const days = [];
  for(let i=6;i>=0;i--){
    const d = new Date(today); d.setDate(d.getDate()-i);
    const dayRecords = records.filter(r=>new Date(r.learnDate).toDateString()===d.toDateString());
    const correct = dayRecords.filter(r=>r.correct).length;
    const accuracy = dayRecords.length>0 ? Math.round(correct/dayRecords.length*100) : 0;
    days.push({ date:d, count:dayRecords.length, accuracy });
  }
  const maxCount = Math.max(...days.map(d=>d.count),1);

  let barHtml = '<div class="simple-bar">';
  days.forEach(d=>{
    const h = d.count>0 ? Math.round(d.count/maxCount*100) : 4;
    const color = d.count===0?'var(--bg3)':d.accuracy>=80?'var(--green)':d.accuracy>=50?'var(--yellow)':'var(--red)';
    barHtml += `<div class="bar-col">
      <div style="font-size:.65rem;color:var(--muted);margin-bottom:2px">${d.count||''}</div>
      <div class="bar-fill" style="height:${h}%;background:${color}"></div>
      <div class="bar-label">${d.date.getMonth()+1}/${d.date.getDate()}</div>
    </div>`;
  });
  barHtml += '</div>';

  // 科目能力概览
  const subjectProgress = computeSubjectProgress(records);
  let abilityHtml = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:.8rem">';
  subjectProgress.forEach(s=>{
    if(s.total===0) return;
    const level = s.accuracy>=80?'优秀':s.accuracy>=60?'良好':s.accuracy>=40?'一般':'薄弱';
    const color = s.accuracy>=80?'var(--green)':s.accuracy>=60?'var(--blue)':s.accuracy>=40?'var(--yellow)':'var(--red)';
    abilityHtml += `<div style="padding:.8rem;border-radius:8px;background:var(--bg2);border-left:3px solid ${color}">
      <div style="font-size:.85rem;font-weight:600">${s.icon} ${s.name}</div>
      <div style="font-size:.78rem;color:var(--muted);margin-top:.2rem">正确率 ${s.accuracy}% · ${level}</div>
    </div>`;
  });
  abilityHtml += '</div>';

  // 科目明细表
  let tableHtml = `<div class="table-wrap" style="margin-top:1rem"><table class="deploy-table" style="width:100%;border-collapse:collapse;font-size:.8rem">
    <thead><tr>
      <th style="text-align:left;padding:.5rem;background:var(--bg2);border-bottom:2px solid var(--rule)">科目</th>
      <th style="padding:.5rem;background:var(--bg2)">题库</th>
      <th style="padding:.5rem;background:var(--bg2)">已做</th>
      <th style="padding:.5rem;background:var(--bg2)">完成率</th>
      <th style="padding:.5rem;background:var(--bg2)">正确率</th>
      <th style="padding:.5rem;background:var(--bg2)">错题</th>
      <th style="text-align:left;padding:.5rem;background:var(--bg2)">薄弱章节</th>
    </tr></thead><tbody>`;
  subjectProgress.forEach(s=>{
    const subWrong = wrongQs.filter(w=>w.subject===s.key);
    const weak = computeWeakPoints(records.filter(r=>r.subject===s.key));
    const completion = s.total>0?Math.round(s.done/s.total*100):0;
    tableHtml += `<tr>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule)">${s.icon} ${s.name}</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);text-align:center">${s.total}</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);text-align:center">${s.done}</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);text-align:center">${completion}%</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);text-align:center;color:${s.accuracy>=60?'var(--green)':'var(--red)'}">${s.accuracy}%</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);text-align:center">${subWrong.length}</td>
      <td style="padding:.5rem;border-bottom:1px solid var(--rule);color:var(--muted)">${weak.length>0?escapeHtml(weak[0].chapter):'—'}</td>
    </tr>`;
  });
  tableHtml += '</tbody></table></div>';

  // 题目对错次数统计
  const byQuestion = {};
  records.forEach(r=>{
    if(!byQuestion[r.questionId]) byQuestion[r.questionId] = { title:r.title, subject:r.subject, correct:0, wrong:0, total:0 };
    byQuestion[r.questionId].total++;
    if(r.correct) byQuestion[r.questionId].correct++;
    else byQuestion[r.questionId].wrong++;
  });
  const questionStats = Object.values(byQuestion).sort((a,b)=>b.wrong-a.wrong);
  let qStatsHtml = `<div class="table-wrap" style="margin-top:1rem"><table class="deploy-table" style="width:100%;border-collapse:collapse;font-size:.8rem">
    <thead><tr>
      <th style="text-align:left;padding:.5rem;background:var(--bg2);border-bottom:2px solid var(--rule)">题目</th>
      <th style="padding:.5rem;background:var(--bg2)">✅ 正确</th>
      <th style="padding:.5rem;background:var(--bg2)">❌ 错误</th>
      <th style="padding:.5rem;background:var(--bg2)">正确率</th>
    </tr></thead><tbody>`;
  questionStats.forEach(qs=>{
    const acc = qs.total>0 ? Math.round(qs.correct/qs.total*100) : 0;
    qStatsHtml += `<tr>
      <td style="padding:.4rem .5rem;border-bottom:1px solid var(--rule)">${escapeHtml(qs.title)}</td>
      <td style="text-align:center;padding:.4rem;border-bottom:1px solid var(--rule);color:var(--green)">${qs.correct}</td>
      <td style="text-align:center;padding:.4rem;border-bottom:1px solid var(--rule);color:var(--red)">${qs.wrong}</td>
      <td style="text-align:center;padding:.4rem;border-bottom:1px solid var(--rule);color:${acc>=60?'var(--green)':'var(--red)'}">${acc}%</td>
    </tr>`;
  });
  qStatsHtml += '</tbody></table></div>';

  el.innerHTML = `
    <div class="chart-card">
      <div class="chart-title">📊 近7天刷题量（颜色代表正确率）</div>
      ${barHtml}
    </div>
    <div class="chart-card">
      <div class="chart-title">💪 科目能力概览</div>
      ${abilityHtml}
    </div>
    <div class="chart-card">
      <div class="chart-title">📋 科目明细</div>
      ${tableHtml}
    </div>
    <div class="chart-card">
      <div class="chart-title">📝 题目对错次数</div>
      ${qStatsHtml}
    </div>`;
}

/* ==========================================================
 * 3.10 收藏夹
 * ========================================================== */
async function renderFavorites(){
  const el = document.getElementById('favContent');
  const favs = (await dbGetAll('favorites')).filter(f=>f.userId===currentUserId);
  favoritedIds = new Set(favs.map(f=>f.questionId));
  let html = `<h3 style="font-size:1rem;margin-bottom:1rem">⭐ 收藏夹（共 ${favs.length} 题）</h3>`;
  if(favs.length===0){
    html += '<div class="empty-state"><div class="es-icon">⭐</div><p>还没有收藏的题目</p></div>';
  } else {
    favs.sort((a,b)=>new Date(b.addedDate)-new Date(a.addedDate));
    favs.forEach(f=>{
      const sub = SUBJECTS[f.subject] || {icon:'📝',name:'未知'};
      html += `<div class="error-card">
        <div class="ec-icon">${sub.icon}</div>
        <div class="ec-body">
          <div class="ec-title">${escapeHtml(f.title)}</div>
          <div class="ec-meta">${sub.name} · ${escapeHtml(f.chapter||'')} · 收藏于 ${formatDate(f.addedDate)}</div>
        </div>
        <div class="ec-actions">
          <button onclick="redoFavorite('${f.questionId}')">练习</button>
          <button onclick="removeFavorite('${f.questionId}')">取消</button>
        </div>
      </div>`;
    });
  }
  el.innerHTML = html;
}

async function redoFavorite(questionId){
  const fav = await dbGetByKey('favorites', `fav_${currentUserId}_${questionId}`);
  if(!fav || !fav.question){
    alert('未找到该题目');
    return;
  }
  currentQuestions = [fav.question];
  currentQuestionIndex = 0;
  switchPanel('quiz');
  renderQuestion();
}

async function removeFavorite(questionId){
  await dbDelete('favorites', `fav_${currentUserId}_${questionId}`);
  favoritedIds.delete(questionId);
  renderFavorites();
}

/* ==========================================================
 * 3.11 我的解析
 * ========================================================== */
async function renderNotes(){
  const el = document.getElementById('notesContent');
  let notes = (await dbGetAll('notes')).filter(n=>n.userId===currentUserId);

  let html = `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;flex-wrap:wrap;gap:.5rem">
    <h3 style="font-size:1rem">📋 我的解析（共 ${notes.length} 条）</h3>
    <div style="display:flex;gap:.5rem">
      <button class="btn btn-outline" style="font-size:.78rem;padding:.4rem .8rem" onclick="exportNotes()">📥 导出</button>
      <button class="btn btn-outline" style="font-size:.78rem;padding:.4rem .8rem" onclick="document.getElementById('noteImportInput').click()">📤 导入</button>
      <input type="file" id="noteImportInput" accept=".json" style="display:none" onchange="importNotes(event)">
    </div>
  </div>`;

  // 过滤栏
  html += '<div class="filter-bar">';
  html += `<button class="filter-pill ${noteFilterSubject==='all'?'active':''}" onclick="setNoteFilter('all')">全部</button>`;
  Object.entries(SUBJECTS).forEach(([key,sub])=>{
    const has = notes.some(n=>n.subject===key);
    if(has) html += `<button class="filter-pill ${noteFilterSubject===key?'active':''}" onclick="setNoteFilter('${key}')">${sub.icon} ${sub.name}</button>`;
  });
  html += '</div>';

  if(noteFilterSubject!=='all'){
    notes = notes.filter(n=>n.subject===noteFilterSubject);
  }

  if(notes.length===0){
    html += '<div class="empty-state"><div class="es-icon">📋</div><p>还没有添加解析笔记，刷题时点击"添加解析"即可记录</p></div>';
  } else {
    notes.sort((a,b)=>new Date(b.createdDate)-new Date(a.createdDate));
    notes.forEach(n=>{
      const sub = SUBJECTS[n.subject] || {icon:'📝',name:'未知'};
      let imgs = '';
      if(n.images && n.images.length>0){
        imgs = '<div class="nc-images">'+n.images.map(src=>`<div class="nc-thumb" onclick="window.open('${src}')"><img src="${src}" style="width:100%;height:100%;object-fit:cover"></div>`).join('')+'</div>';
      }
      html += `<div class="note-card">
        <div class="nc-header">
          <span class="tag tag-blue">${sub.icon} ${sub.name}</span>
          <span style="font-size:.72rem;color:var(--muted)">${escapeHtml(n.chapter||'')}</span>
          <span class="nc-title">${escapeHtml(n.title)}</span>
        </div>
        ${n.text?`<div style="font-size:.85rem;line-height:1.7;white-space:pre-wrap">${escapeHtml(n.text)}</div>`:''}
        ${imgs}
        <div style="font-size:.72rem;color:var(--muted);margin-top:.4rem">📅 ${formatDate(n.createdDate)}</div>
        <div class="nc-actions">
          <button class="btn-sm" onclick="editNote('${n.id}')">编辑</button>
          <button class="btn-sm" onclick="deleteNote('${n.id}')">删除</button>
        </div>
      </div>`;
    });
  }
  el.innerHTML = html;
}

function setNoteFilter(subject){
  noteFilterSubject = subject;
  renderNotes();
}

function openNoteModal(questionId){
  currentNoteTarget = questionId;
  const q = allQuestions.find(q=>q.id===questionId);
  document.getElementById('noteTarget').textContent = '题目：'+(q?q.title:questionId);
  document.getElementById('noteText').value = '';
  currentNoteImages = [];
  document.getElementById('noteImagePreview').innerHTML = '';
  document.getElementById('noteModal').classList.add('show');
}

function closeNoteModal(){
  document.getElementById('noteModal').classList.remove('show');
}

function previewNoteImages(event){
  const files = Array.from(event.target.files);
  files.forEach(file=>{
    const reader = new FileReader();
    reader.onload = (e)=>{
      currentNoteImages.push(e.target.result);
      const img = document.createElement('img');
      img.src = e.target.result;
      document.getElementById('noteImagePreview').appendChild(img);
    };
    reader.readAsDataURL(file);
  });
}

async function saveNote(){
  const text = document.getElementById('noteText').value.trim();
  if(!text && currentNoteImages.length===0){
    alert('请输入解析内容或上传图片');
    return;
  }
  const q = allQuestions.find(q=>q.id===currentNoteTarget);
  const id = `note_${currentUserId}_${currentNoteTarget}_${Date.now()}`;
  await dbAdd('notes', {
    id, userId:currentUserId, questionId:currentNoteTarget,
    subject:q?q.subject:'', system:q?q.system:'', chapter:q?q.chapter:'',
    title:q?q.title:currentNoteTarget,
    text, images:currentNoteImages, createdDate:new Date().toISOString()
  });
  closeNoteModal();
  // 如果当前在解析页则刷新
  if(document.getElementById('panel-notes').classList.contains('active')) renderNotes();
}

async function editNote(noteId){
  const note = await dbGetByKey('notes', noteId);
  if(!note) return;
  currentNoteTarget = note.questionId;
  document.getElementById('noteTarget').textContent = '题目：'+note.title;
  document.getElementById('noteText').value = note.text||'';
  currentNoteImages = note.images||[];
  const preview = document.getElementById('noteImagePreview');
  preview.innerHTML = '';
  currentNoteImages.forEach(src=>{ const img=document.createElement('img'); img.src=src; preview.appendChild(img); });
  document.getElementById('noteModal').classList.add('show');
  // 改保存按钮行为为更新
  document.querySelector('.btn-save').onclick = async ()=>{
    const newText = document.getElementById('noteText').value.trim();
    note.text = newText;
    note.images = currentNoteImages;
    await dbAdd('notes', note);
    closeNoteModal();
    document.querySelector('.btn-save').onclick = saveNote;
    renderNotes();
  };
}

async function deleteNote(noteId){
  if(!confirm('确定删除该解析？')) return;
  await dbDelete('notes', noteId);
  renderNotes();
}

